import { useCallback, useEffect, useRef, useState } from 'react';
import type { FormEvent } from 'react';
import { Activity, ArrowDown, ArrowLeft, ArrowRight, ArrowUp, AudioLines, BookOpen, Check, CheckCheck, ChevronLeft, ChevronRight, CircleAlert, Clock3, Disc3, FolderCheck, FolderSearch, ImagePlus, Library, ListMusic, LoaderCircle, LockKeyhole, LogOut, Moon, Music2, Plus, RefreshCw, Save, Search, Settings2, ShieldCheck, SlidersHorizontal, Sun, Trash2, Upload, WandSparkles, X } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { api, messageFor, setSession } from './api';
import { ReportView } from './ReportView';
import { AnalysisPanel } from './AnalysisPanel';
import { CueView } from './CueView';
import { changedTags } from './edits';
import { formatTime, parseLyrics, parseTime, serializeLyrics, validateLyrics } from './lyrics';
import type { LyricLine } from './lyrics';
import type { Job, Session, Summary, Tags, Track, TrackPage } from './types';

type Page = 'library' | 'review' | 'lyrics' | 'jobs' | 'ready' | 'settings' | 'reports';
const navigation: Array<{ id: Page; title: string; icon: LucideIcon }> = [
  { id: 'reports', title: 'Отчеты', icon: BookOpen }, { id: 'library', title: 'Коллекция', icon: Library }, { id: 'review', title: 'Проверка', icon: CheckCheck },
  { id: 'lyrics', title: 'Тексты', icon: ListMusic }, { id: 'jobs', title: 'Обработка', icon: Activity },
  { id: 'ready', title: 'Готовая коллекция', icon: FolderCheck }, { id: 'settings', title: 'Настройки', icon: Settings2 },
];
const jobNames: Record<string, string> = { extract_cue: 'Извлечение CUE', replaygain: 'Измерение ReplayGain', recognize: 'Распознавание аудиоотпечатков', transcribe: 'Проверка содержимого ASR', align: 'Сопоставление текста с аудио', analyze: 'Поиск метаданных и текстов', scan: 'Сканирование', audit: 'Проверка аудио', apply: 'Запись изменений', rollback: 'Откат изменений', publish: 'Публикация' };
const states: Record<string, string> = { queued: 'В очереди', running: 'В работе', completed: 'Завершено', completed_with_errors: 'Завершено с ошибками', succeeded: 'Завершено', failed: 'Ошибка', canceled: 'Отменено', cancelled: 'Отменено', cancelled_partial: 'Отменено частично', interrupted: 'Прервано', needs_review: 'Нужно решение', pending: 'Ожидание', partial: 'Частично', idle: 'Ожидает работу', online: 'В сети', offline: 'Нет связи', ready: 'Готово', ok: 'Проверено', indexed: 'В каталоге', accepted: 'Принято', missing: 'Файл недоступен', conflict: 'Конфликт версий', error: 'Ошибка', scanned: 'В каталоге', unsupported: 'Только чтение' };
const activeStates = ['queued', 'running', 'pending'];
const fields = [{ key: 'title', title: 'Название' }, { key: 'artist', title: 'Исполнитель' }, { key: 'album', title: 'Альбом' }, { key: 'date', title: 'Год / дата' }, { key: 'tracknumber', title: 'Номер трека' }];
const textTag = (tags: Tags | undefined, key: string) => { const value = tags?.[key]; return Array.isArray(value) ? value.join('; ') : value == null ? '' : String(value); };
const titleOf = (track: Track) => textTag(track.tags, 'title') || track.filename || track.relative_path.split('/').pop() || 'Без названия';
const durationOf = (value?: number) => value && Number.isFinite(value) ? `${Math.floor(value / 60)}:${String(Math.floor(value % 60)).padStart(2, '0')}` : '-';
const dateOf = (value?: string | null) => value ? new Date(value).toLocaleString('ru-RU', { dateStyle: 'short', timeStyle: 'short' }) : 'Нет данных';
const countOf = (value?: number) => value == null ? '-' : value.toLocaleString('ru-RU');

function Spinner({ label = 'Загрузка' }: { label?: string }) { return <span className="loading"><LoaderCircle className="spin" size={20} aria-hidden="true" />{label}</span>; }
function ErrorBox({ message, retry }: { message: string; retry?: () => void }) { return <div className="notice error" role="alert"><CircleAlert size={20} aria-hidden="true" /><div>{message}</div>{retry && <button className="text-button" onClick={retry}>Повторить</button>}</div>; }
function Badge({ children, tone = '' }: { children: React.ReactNode; tone?: string }) { return <span className={`badge ${tone}`}>{children}</span>; }
function Cover({ track, large = false, preview }: { track: Track; large?: boolean; preview?: string }) {
  const [failed, setFailed] = useState(false);
  const source = preview || (track.has_art ? `/api/tracks/${encodeURIComponent(track.id)}/art?v=${track.sha256}` : '');
  useEffect(() => setFailed(false), [source]);
  return <div className={`cover ${large ? 'large' : ''}`}>{source && !failed ? <img src={source} alt={`Обложка: ${titleOf(track)}`} onError={() => setFailed(true)} /> : <Disc3 size={large ? 56 : 24} strokeWidth={1.4} aria-label="Нет обложки" />}</div>;
}

function Login({ onLogin, initialError }: { onLogin: () => Promise<void>; initialError?: string }) {
  const [username, setUsername] = useState(''); const [password, setPassword] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState(initialError || '');
  useEffect(() => { if (initialError) setError(initialError); }, [initialError]);
  async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); setError(''); try { await api('/auth/login', { method: 'POST', body: JSON.stringify({ username, password }) }); setPassword(''); await onLogin(); } catch (err) { setError(messageFor(err)); } finally { setBusy(false); } }
  return <div className="login-layout"><div className="login-story"><div className="brand"><span className="brand-mark"><AudioLines /></span>Фонотека</div><div><div className="eyebrow">ВАША МУЗЫКА. В ПОРЯДКЕ.</div><h1>У каждой песни<br />свое место.</h1><p>Метаданные, обложки и слова, которые звучат вовремя. Ваша коллекция под вашим контролем.</p><div className="record-illustration" aria-hidden="true"><div className="record"><div /></div><span className="record-label"><Music2 size={19} />Личная коллекция</span></div></div><span className="story-foot"><ShieldCheck size={16} />Один владелец. Собственное хранилище.</span></div><main className="login-main"><form className="login-card" onSubmit={submit}><div className="icon-surface"><LockKeyhole size={27} /></div><h2>С возвращением</h2><p className="muted">Войдите, чтобы открыть свою фонотеку.</p>{error && <ErrorBox message={error} />}<label>Имя владельца<input autoComplete="username" value={username} onChange={event => setUsername(event.target.value)} required autoFocus /></label><label>Пароль<input type="password" autoComplete="current-password" value={password} onChange={event => setPassword(event.target.value)} required /></label><button className="button primary wide" type="submit" disabled={busy || !username || !password}>{busy ? <Spinner label="Входим" /> : <>Открыть фонотеку<ArrowRight size={18} /></>}</button><p className="login-note">Доступ к этому экземпляру есть только у владельца. Учетная запись настраивается при установке.</p></form><span className="muted small">Фонотека · первая рабочая версия</span></main></div>;
}

export default function App() {
  const [session, updateSession] = useState<Session | null>(null); const [sessionError, setSessionError] = useState('');
  const [page, setPage] = useState<Page>('library'); const [summary, setSummary] = useState<Summary | null>(null);
  const [tracks, setTracks] = useState<TrackPage | null>(null); const [jobs, setJobs] = useState<Job[]>([]);
  const [search, setSearch] = useState(''); const [query, setQuery] = useState(''); const [filter, setFilter] = useState('all'); const [pageNumber, setPageNumber] = useState(1);
  const [selected, setSelected] = useState<Track | null>(null); const [selectedId, setSelectedId] = useState(''); const [dirty, setDirty] = useState(false);
  const [loading, setLoading] = useState(false); const [detailLoading, setDetailLoading] = useState(false); const [error, setError] = useState(''); const [notice, setNotice] = useState(''); const [busy, setBusy] = useState(false);
  const [theme, setTheme] = useState(() => { try { return localStorage.getItem('phonoteka-theme') || 'system'; } catch { return 'system'; } });
  const requestSequence = useRef(0); const detailSequence = useRef(0);
  const refreshSession = useCallback(async () => { try { const value = await api<Session>('/auth/session'); setSession(value); updateSession(value); setSessionError(''); } catch (err) { setSessionError(messageFor(err)); } }, []);
  useEffect(() => { void refreshSession(); }, [refreshSession]);
  useEffect(() => { const expired = () => { updateSession({ authenticated: false }); setSession({ authenticated: false }); setSessionError('Сессия завершилась. Войдите снова.'); }; window.addEventListener('session-expired', expired); return () => window.removeEventListener('session-expired', expired); }, []);
  useEffect(() => { document.documentElement.dataset.theme = theme; try { localStorage.setItem('phonoteka-theme', theme); } catch { /* Theme still works without storage. */ } }, [theme]);
  useEffect(() => { const timer = window.setTimeout(() => { setQuery(search); setPageNumber(1); }, 300); return () => clearTimeout(timer); }, [search]);
  useEffect(() => { const beforeUnload = (event: BeforeUnloadEvent) => { if (dirty) { event.preventDefault(); event.returnValue = ''; } }; window.addEventListener('beforeunload', beforeUnload); return () => window.removeEventListener('beforeunload', beforeUnload); }, [dirty]);
  const loadTracks = useCallback(async () => {
    if (!session?.authenticated) return;
    const current = ++requestSequence.current; setLoading(true);
    try { const result = await api<TrackPage>(`/tracks?search=${encodeURIComponent(query)}&page=${pageNumber}&page_size=30&filter=${encodeURIComponent(filter)}`); if (current === requestSequence.current) setTracks(result); }
    catch (err) { if (current === requestSequence.current) setError(messageFor(err)); }
    finally { if (current === requestSequence.current) setLoading(false); }
  }, [session?.authenticated, query, pageNumber, filter]);
  const loadStatus = useCallback(async () => {
    if (!session?.authenticated) return;
    const results = await Promise.allSettled([api<Summary>('/summary'), api<{ items: Job[] }>('/jobs')]);
    if (results[0].status === 'fulfilled') setSummary(results[0].value); else setError(messageFor(results[0].reason));
    if (results[1].status === 'fulfilled') setJobs(results[1].value.items); else setError(messageFor(results[1].reason));
  }, [session?.authenticated]);
  useEffect(() => { void loadTracks(); }, [loadTracks]);
  useEffect(() => { void loadStatus(); if (!session?.authenticated) return; const timer = window.setInterval(() => { if (!document.hidden) { void loadStatus(); } }, 4000); return () => clearInterval(timer); }, [loadStatus, session?.authenticated]);
  const completedJobs = jobs.filter(job => !activeStates.includes(job.state)).map(job => `${job.id}:${job.state}`).join(',');
  useEffect(() => { if (completedJobs) void loadTracks(); }, [completedJobs, loadTracks]);
  const clearDirty = () => !dirty || window.confirm('В карточке есть несохраненные изменения. Перейти и потерять этот черновик?');
  function navigate(next: Page) { if ((next === 'review' || next === 'lyrics') || clearDirty()) { setPage(next); setError(''); if (next !== 'review' && next !== 'lyrics') { setDirty(false); setSelected(null); setSelectedId(''); } if (next === 'ready') { setFilter('published'); setPageNumber(1); } else if (page === 'ready') { setFilter('all'); setPageNumber(1); } } }
  async function openTrack(track: Track, target: Page = 'review') {
    if (!clearDirty()) return;
    const current = ++detailSequence.current; setPage(target); setSelectedId(track.id); setDetailLoading(true); setError('');
    try { const result = await api<Track>(`/tracks/${encodeURIComponent(track.id)}`); if (current === detailSequence.current) { setSelected(result); setDirty(false); } } catch (err) { if (current === detailSequence.current) setError(messageFor(err)); } finally { if (current === detailSequence.current) setDetailLoading(false); }
  }
  async function submitJob(kind: string, ids: string[] = [], params: Record<string, unknown> = {}) {
    setBusy(true); setError('');
    try { const job = await api<Job>('/jobs', { method: 'POST', headers: { 'Idempotency-Key': crypto.randomUUID() }, body: JSON.stringify({ kind, track_ids: ids, params }) }); setNotice(`${jobNames[kind] || kind}: задача добавлена в очередь.`); await loadStatus(); return job; } catch (err) { setError(messageFor(err)); return null; } finally { setBusy(false); }
  }
  async function logout() { if (!clearDirty()) return; try { await api('/auth/logout', { method: 'POST' }); setSession({ authenticated: false }); updateSession({ authenticated: false }); setSelected(null); setTracks(null); setSummary(null); setDirty(false); } catch (err) { setError(messageFor(err)); } }
  if (!session) return <main className="loading-page"><div className="brand"><AudioLines />Фонотека</div>{sessionError ? <ErrorBox message={sessionError} retry={() => void refreshSession()} /> : <Spinner label="Подключаемся к фонотеке" />}</main>;
  if (!session.authenticated) return <Login onLogin={refreshSession} initialError={sessionError} />;
  const activeJobs = jobs.filter(job => activeStates.includes(job.state));
  const isEditor = page === 'review' || page === 'lyrics';
  const headings: Record<Page, [string, string]> = { reports: ['Коллекция в деталях', 'Ошибки, дубликаты, альбомы и результаты подготовки.'], library: ['Все, что звучит', 'Ваша коллекция, по одному треку за раз.'], review: ['Внимание к деталям', 'Проверьте изменения перед записью в файл.'], lyrics: ['Слова в нужный момент', 'Построчная синхронизация с полным аудиофайлом.'], jobs: ['Работа идет', 'Независимые задачи и понятный результат каждой.'], ready: ['Готово к прослушиванию', 'Опубликованные версии хранятся отдельно от рабочей копии.'], settings: ['Под вашим контролем', 'Состояние экземпляра и возможности этой версии.'] };
  return <div className="app-shell"><a className="skip-link" href="#main-content">Перейти к содержимому</a><aside className="sidebar"><a className="brand" href="#" onClick={event => { event.preventDefault(); navigate('library'); }}><span className="brand-mark"><AudioLines size={25} /></span><span>Фонотека</span></a><span className="sidebar-label">МОЯ БИБЛИОТЕКА</span><nav aria-label="Основная навигация">{navigation.map(item => <button key={item.id} aria-label={item.title} onClick={() => navigate(item.id)} aria-current={page === item.id ? 'page' : undefined}><item.icon size={21} /><span>{item.title}</span>{item.id === 'jobs' && activeJobs.length > 0 && <span className="nav-count">{activeJobs.length}</span>}</button>)}</nav><div className="sidebar-bottom"><div className="storage-note"><ShieldCheck size={20} /><div><strong>Рабочая копия</strong><span>Оригиналы сохранены отдельно</span></div></div><div className="sidebar-account"><div className="avatar">{(session.username || 'В')[0].toUpperCase()}</div><div><strong>{session.username || 'Владелец'}</strong><span>Личный экземпляр</span></div><button className="icon-button" aria-label="Выйти" title="Выйти" onClick={() => void logout()}><LogOut size={18} /></button></div></div></aside><div className="main-shell"><header className="topbar"><span className="breadcrumb">Моя фонотека<span>/</span>{navigation.find(item => item.id === page)?.title}</span><div className="topbar-actions"><Badge>0.3 · Alpha</Badge><button className="icon-button" title="Сменить тему" aria-label="Сменить светлую или темную тему" onClick={() => setTheme(theme === 'dark' ? 'light' : theme === 'light' ? 'dark' : matchMedia('(prefers-color-scheme: dark)').matches ? 'light' : 'dark')}>{theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}</button></div></header><main id="main-content" tabIndex={-1}><div className="page-heading"><div><div className="eyebrow">{page === 'library' ? 'МУЗЫКА, КОТОРУЮ ВЫ СОБРАЛИ' : navigation.find(item => item.id === page)?.title.toUpperCase()}</div><h1>{headings[page][0]}</h1><p>{headings[page][1]}</p></div>{page === 'library' && <button className="button primary" onClick={() => void submitJob('scan')} disabled={busy || activeJobs.some(job => job.kind === 'scan')}><FolderSearch size={19} />{activeJobs.some(job => job.kind === 'scan') ? 'Сканирование идет' : 'Сканировать коллекцию'}</button>}</div>{error && <ErrorBox message={error} retry={() => { setError(''); void loadTracks(); void loadStatus(); }} />}{notice && <div className="notice success" role="status"><Check size={20} /><span>{notice}</span><button className="icon-button" aria-label="Закрыть сообщение" onClick={() => setNotice('')}><X size={17} /></button></div>}{summary?.read_only && <div className="notice warning"><LockKeyhole size={20} /><span>Хранилище открыто для чтения. Запись и публикация недоступны. Причина и режим показаны в настройках.</span></div>}
      {page === 'library' && <><div className="library-tools"><button className="button secondary" disabled={busy || !summary?.capabilities.metadata_search || activeJobs.some(job => job.kind === 'analyze')} onClick={() => void submitJob('analyze', [], {scope:'all'})}><WandSparkles size={18}/>Подготовить всю коллекцию</button><button className="button secondary" disabled={busy || !summary?.capabilities.recognition || activeJobs.some(job => job.kind === 'recognize')} onClick={() => void submitJob('recognize', [], {scope:'all'})}>Распознать всю коллекцию</button><button className="button subtle" disabled={busy || !summary?.capabilities.metadata_search || activeJobs.some(job => job.kind === 'analyze')} onClick={() => void submitJob('analyze', [], {scope:'pending'})}>Повторить недоступные источники</button><button className="button subtle" disabled={busy || !summary?.capabilities.recognition || activeJobs.some(job => job.kind === 'recognize')} onClick={() => void submitJob('recognize', [], {scope:'pending'})}>Продолжить распознавание</button><span className="muted small">Результаты сохраняются как предложения</span></div><section className="stats" aria-label="Состояние коллекции"><Stat label="Записей в коллекции" value={summary?.total} icon={Music2} accent /><Stat label="Без обложки" value={summary?.missing_art} icon={ImagePlus} /><Stat label="Без текста" value={summary?.missing_lyrics} icon={ListMusic} /><Stat label="Нужно проверить" value={summary?.needs_review} icon={CheckCheck} /></section><section className="panel collection-panel"><div className="panel-heading"><div><h2>Ваша музыка</h2><span className="muted small">Теги, обложки и тексты из файлов рабочей копии{summary?.cue_sheets ? ` · CUE: ${summary.cue_sheets} альбомов, ${summary.cue_tracks} композиций` : ''}</span></div><button className="icon-button" aria-label="Обновить коллекцию" onClick={() => { void loadTracks(); void loadStatus(); }}><RefreshCw size={18} /></button></div><TrackFilters search={search} onSearch={setSearch} filter={filter} onFilter={value => { setFilter(value); setPageNumber(1); }} /><TrackList tracks={tracks} loading={loading} selectedId={selectedId} onSelect={track => void openTrack(track)} /><Pagination tracks={tracks} page={pageNumber} onPage={setPageNumber} loading={loading} /></section><div className="quiet-note"><ShieldCheck size={17} />Изменения сначала сохраняются как предложение. Запись в файл запускается отдельным действием.</div></>}
      {isEditor && <div className={`editor-layout ${selected ? 'has-selection' : ''}`}><section className="panel track-queue"><div className="panel-heading"><h2>Треки</h2><span className="muted small">{countOf(tracks?.total)}</span></div><TrackFilters compact search={search} onSearch={setSearch} filter={filter} onFilter={value => { setFilter(value); setPageNumber(1); }} /><div className="queue-tracks">{tracks?.items.map(track => <button key={track.id} className={`queue-track ${selectedId === track.id ? 'selected' : ''}`} onClick={() => void openTrack(track, page)}><Cover track={track} /><span><strong>{titleOf(track)}</strong><small>{textTag(track.tags, 'artist') || 'Исполнитель не указан'}</small><span className="queue-meta">{track.format.toUpperCase()}{track.proposal?.input_sha256 === track.sha256 ? ' · Предложение' : ''}</span></span>{track.proposal && <span className="proposal-dot" aria-label="Есть предложение" />}</button>)}{loading && <Spinner />}{!loading && tracks?.items.length === 0 && <div className="empty compact"><Search size={25} /><p>Треков не найдено</p></div>}</div><Pagination compact tracks={tracks} page={pageNumber} onPage={setPageNumber} loading={loading} /></section><section className="editor-content">{selected?.cue_sheets?.length ? <div className="notice info cue-links"><Disc3 size={20} /><div>{selected.cue_album_image && <p>Это альбомный образ. Изменение и публикация файла заблокированы, чтобы сохранить все композиции.</p>}{selected.cue_sheets.map(sheet => <button className="button subtle" key={sheet.id} onClick={() => { void api<Track>(`/tracks/${encodeURIComponent(sheet.id)}`).then(item => openTrack(item, page)).catch(err => setError(messageFor(err))); }}>Открыть CUE: {sheet.title} ({sheet.track_count})</button>)}</div></div> : null}{detailLoading ? <div className="panel empty"><Spinner label="Открываем карточку" /></div> : selected ? selected.format === 'cue' ? <CueView enabled={!!summary?.capabilities.cue_export} busy={busy} onExtract={() => void submitJob('extract_cue', [selected.id])} key={`${selected.id}:${selected.sha256}:${selected.revision}`} track={selected} onBack={() => { setSelected(null); setSelectedId(''); }} onRefresh={() => { void openTrack(selected, page); }} /> : <TrackEditor key={`${selected.id}:${selected.proposal?.id || ''}:${selected.sha256}`} track={selected} page={page} summary={summary} busy={busy} onDirty={setDirty} onTab={setPage} onBack={() => { if (clearDirty()) { setSelected(null); setSelectedId(''); setDirty(false); } }} onRefresh={() => { void openTrack(selected, page); }} onSave={async body => { await api(`/tracks/${encodeURIComponent(selected.id)}/proposal`, { method: 'POST', headers: { 'If-Match': `"${selected.sha256}"` }, body: JSON.stringify(body) }); setDirty(false); const result = await api<Track>(`/tracks/${encodeURIComponent(selected.id)}`); setSelected(result); setNotice('Предложение сохранено. Файл пока не изменен.'); void loadTracks(); }} onJob={async (kind, params) => { const job = await submitJob(kind, [selected.id], params); if (job) { setNotice(`${jobNames[kind]}: задача принята. Результат появится в разделе «Обработка».`); } }} /> : <div className="panel empty editor-empty"><div className="icon-surface"><SlidersHorizontal size={30} /></div><h2>Выберите трек</h2><p>Откройте карточку слева, чтобы проверить теги,<br />обложку и синхронизированный текст.</p></div>}</section></div>}
      {page === 'jobs' && <JobsView jobs={jobs} refresh={loadStatus} onCancel={async id => { try { await api(`/jobs/${encodeURIComponent(id)}/cancel`, { method: 'POST' }); setNotice('Запрошена отмена. Текущая запись файла завершится безопасно. Уже завершенные изменения сохранятся.'); await loadStatus(); } catch (err) { setError(messageFor(err)); } }} />}
      {page === 'ready' && <><div className="notice info"><FolderCheck size={21} /><span>Здесь показаны опубликованные версии. Передача на телефон и проверка в Poweramp выполняются отдельно.</span></div><section className="panel collection-panel"><div className="panel-heading"><h2>Опубликованные треки</h2><Badge>{countOf(tracks?.total)}</Badge></div><TrackList tracks={tracks} loading={loading} selectedId="" onSelect={track => void openTrack(track)} /><Pagination tracks={tracks} page={pageNumber} onPage={setPageNumber} loading={loading} /></section></>}
      {page === 'reports' && <ReportView onOpen={id=>{void api<Track>(`/tracks/${encodeURIComponent(id)}`).then(track=>openTrack(track)).catch(err=>setError(messageFor(err)));}}/>}
      {page === 'settings' && <SettingsView summary={summary} theme={theme} setTheme={setTheme} />}
      <footer className="app-footer"><span><ShieldCheck size={14} />Личная коллекция · рабочая копия</span><span>{summary?.version || 'Подключение к серверу'} · {summary?.worker ? `Обработчик: ${states[summary.worker.state] || summary.worker.state}` : 'Состояние обработчика неизвестно'}</span></footer>
    </main></div></div>;
}

function Stat({ label, value, icon: Icon, accent }: { label: string; value?: number; icon: LucideIcon; accent?: boolean }) { return <div className={`stat ${accent ? 'accent' : ''}`}><div><span>{label}</span><strong>{countOf(value)}</strong></div><span className="stat-icon"><Icon size={23} /></span></div>; }
function TrackFilters({ search, onSearch, filter, onFilter, compact = false }: { search: string; onSearch: (value: string) => void; filter: string; onFilter: (value: string) => void; compact?: boolean }) { return <div className={`filters ${compact ? 'compact-filters' : ''}`}><label className="search-field"><Search size={18} /><input aria-label="Поиск по коллекции" placeholder="Найти трек, исполнителя, альбом" value={search} onChange={event => onSearch(event.target.value)} />{search && <button className="icon-button" onClick={() => onSearch('')} aria-label="Очистить поиск"><X size={15} /></button>}</label><label className="filter-select"><SlidersHorizontal size={16} /><select aria-label="Фильтр треков" value={filter} onChange={event => onFilter(event.target.value)}><option value="all">Все записи</option><option value="cue">Альбомы CUE</option><option value="review">Нужно проверить</option><option value="missing_lyrics">Без текста</option><option value="missing_art">Без обложки</option><option value="published">Опубликованы</option></select></label></div>; }
function TrackList({ tracks, loading, selectedId, onSelect }: { tracks: TrackPage | null; loading: boolean; selectedId: string; onSelect: (track: Track) => void }) { return <div className="track-list" aria-busy={loading}><div className="track-table-head"><span>ТРЕК / ИСПОЛНИТЕЛЬ</span><span>ФОРМАТ</span><span>ТЕГИ</span><span>ОБЛОЖКА</span><span>ТЕКСТ</span><span /></div>{!tracks ? <div className="empty"><Spinner /></div> : tracks.items.length === 0 ? <div className="empty"><div className="icon-surface"><Library size={30} /></div><h3>{tracks.total ? 'Нет треков на этой странице' : 'Пока ничего не найдено'}</h3><p>Измените фильтр или запустите сканирование рабочей коллекции.</p></div> : tracks.items.map(track => <button className={`track-row ${selectedId === track.id ? 'selected' : ''}`} key={track.id} onClick={() => onSelect(track)}><span className="track-name"><Cover track={track} /><span><strong>{titleOf(track)}</strong><small>{textTag(track.tags, 'artist') || 'Исполнитель не указан'}{textTag(track.tags, 'album') && ` · ${textTag(track.tags, 'album')}`}</small><span className="track-mobile-meta">{track.format.toUpperCase()} · {durationOf(track.duration)}{track.proposal?.input_sha256 === track.sha256 ? ' · Предложение' : ''}</span></span></span><span className="format-cell">{track.format.toUpperCase()}<small>{durationOf(track.duration)}</small></span><span className="state-cell"><StatusMark ok={!!textTag(track.tags, 'title') && !!textTag(track.tags, 'artist')} label="Теги" /></span><span className="state-cell"><StatusMark ok={track.has_art} label="Обложка" /></span><span className="lyric-state"><Badge tone={track.lrc ? 'good' : track.lyrics ? 'warm' : ''}>{track.lrc ? 'С таймкодами' : track.lyrics ? 'Без таймкодов' : 'Нет текста'}</Badge></span><ChevronRight className="row-arrow" size={18} /></button>)}</div>; }
function StatusMark({ ok, label }: { ok: boolean; label: string }) { return <span className={`status-mark ${ok ? 'good' : ''}`} aria-label={`${label}: ${ok ? 'есть' : 'не указаны'}`}>{ok ? <Check size={18} /> : <span>-</span>}</span>; }
function Pagination({ tracks, page, onPage, loading, compact = false }: { tracks: TrackPage | null; page: number; onPage: (page: number) => void; loading: boolean; compact?: boolean }) { const pages = tracks ? Math.max(1, Math.ceil(tracks.total / tracks.page_size)) : 1; return <div className={`pagination ${compact ? 'compact' : ''}`}><span className="muted small">{compact ? `${page} / ${pages}` : tracks ? `Показано ${tracks.items.length ? (page - 1) * tracks.page_size + 1 : 0}-${Math.min(page * tracks.page_size, tracks.total)} из ${countOf(tracks.total)}` : 'Загрузка каталога'}</span><div><button className="icon-button" disabled={loading || page <= 1} onClick={() => onPage(page - 1)} aria-label="Предыдущая страница"><ChevronLeft size={18} /></button><button className="icon-button" disabled={loading || page >= pages} onClick={() => onPage(page + 1)} aria-label="Следующая страница"><ChevronRight size={18} /></button></div></div>; }

type EditorProps = { track: Track; page: Page; summary: Summary | null; busy: boolean; onDirty: (value: boolean) => void; onTab: (page: Page) => void; onBack: () => void; onRefresh: () => void; onSave: (body: Record<string, unknown>) => Promise<void>; onJob: (kind: string, params?: Record<string, unknown>) => Promise<void> };
function TrackEditor({ track, page, summary, busy, onDirty, onTab, onBack, onRefresh, onSave, onJob }: EditorProps) {
  const activeProposal = track.proposal?.input_sha256 === track.sha256 ? track.proposal : null;
  const [draft, setDraft] = useState<Record<string, string>>(() => Object.fromEntries(fields.map(field => [field.key, textTag(activeProposal?.tags && field.key in activeProposal.tags ? activeProposal.tags : track.tags, field.key)])));
  const [lrc, setLrc] = useState(activeProposal?.lrc ?? track.lrc ?? ''); const [lyricsTouched, setLyricsTouched] = useState(false); const [cover, setCover] = useState(''); const [saving, setSaving] = useState(false); const [localError, setLocalError] = useState('');
  const [changed, setChanged] = useState(false); const [audioTime, setAudioTime] = useState(0); const [audioSupported, setAudioSupported] = useState(false); const [audioError, setAudioError] = useState(''); const audioRef = useRef<HTMLAudioElement>(null);
  const writable = track.can_write && !summary?.read_only;
  const touch = () => { setChanged(true); onDirty(true); };
  let hasUntimed = false; let lyricsInvalid = '';
  try { const parsed = parseLyrics(lrc); hasUntimed = parsed.lines.some(line => line.time === null && line.text.trim()); lyricsInvalid = validateLyrics(parsed.lines, track.duration) || ''; } catch (err) { lyricsInvalid = messageFor(err); }
  async function save() { setSaving(true); setLocalError(''); try { const tags = changedTags(track.tags, draft, activeProposal?.tags); const body: Record<string, unknown> = { tags }; if (activeProposal) body.base_proposal_id = activeProposal.id; if (lyricsTouched || activeProposal?.lrc != null) body.lrc = lrc; if (cover) body.cover = cover; await onSave(body); setChanged(false); onDirty(false); } catch (err) { setLocalError(messageFor(err)); } finally { setSaving(false); } }
  async function importCover(file?: File) { if (!file) return; setLocalError(''); if (!['image/jpeg', 'image/png'].includes(file.type) || file.size > 10 * 1024 * 1024) { setLocalError('Выберите JPEG или PNG размером до 10 МБ.'); return; } const reader = new FileReader(); reader.onerror = () => setLocalError('Не удалось прочитать изображение.'); reader.onload = () => { setCover(String(reader.result)); touch(); }; reader.readAsDataURL(file); }
  const applyBlocked = !writable || !summary?.capabilities.apply || !activeProposal || changed || hasUntimed || !!lyricsInvalid || busy || saving;
  return <><AnalysisPanel track={track} enabled={!!summary?.capabilities.metadata_search} recognitionEnabled={!!summary?.capabilities.recognition} asrEnabled={!!summary?.capabilities.asr} busy={busy} changed={changed} onJob={onJob} onRefresh={onRefresh}/><div className="panel editor-panel"><div className="track-detail-heading"><button className="icon-button mobile-back" onClick={onBack} aria-label="Назад к списку"><ArrowLeft size={21} /></button><Cover track={track} large preview={cover} /><div className="track-detail-title"><span className="eyebrow">{track.format.toUpperCase()} · {durationOf(track.duration)} · РАБОЧАЯ КОПИЯ</span><h2>{titleOf(track)}</h2><p>{textTag(track.tags, 'artist') || 'Исполнитель не указан'}</p><div className="badge-row"><Badge tone={changed ? 'warm' : activeProposal ? 'purple' : ''}>{changed ? 'Есть несохраненные изменения' : activeProposal ? 'Предложение сохранено' : 'Данные из файла'}</Badge>{!track.can_write && <Badge>Только чтение</Badge>}</div></div><button className="icon-button refresh-detail" aria-label="Обновить карточку" title="Обновить данные файла" onClick={onRefresh}><RefreshCw size={18} /></button></div><div className="editor-tabs" role="tablist" aria-label="Редактор трека"><button role="tab" aria-selected={page === 'review'} onClick={() => onTab('review')}><SlidersHorizontal size={17} />Метаданные</button><button role="tab" aria-selected={page === 'lyrics'} onClick={() => onTab('lyrics')}><ListMusic size={18} />Текст и время</button></div>{localError && <ErrorBox message={localError} />}{track.proposal && !activeProposal && <div className="notice info"><RefreshCw size={19} /><span>Предыдущее предложение относится к другой версии файла. Для новых изменений создайте актуальное предложение.</span></div>}{!writable && <div className="notice warning"><LockKeyhole size={19} /><span>Редактирование этого файла недоступно. Запись зависит от формата, состояния файла и проверки хранилища.</span></div>}
      {page === 'review' && <div className="metadata-content"><div className="section-intro"><h3>Проверьте метаданные</h3><Badge tone="purple">Ручное предложение</Badge></div><p className="muted small">Исходные значения остаются видимыми. Сохранение предложения еще не изменяет аудиофайл.</p><div className="metadata-grid"><div className="metadata-labels"><span>ПОЛЕ</span><span>В ФАЙЛЕ</span><span>ПРЕДЛОЖЕНИЕ</span></div>{fields.map(field => <div key={field.key} className={`metadata-row ${draft[field.key] !== textTag(track.tags, field.key) ? 'modified' : ''}`}><label htmlFor={`tag-${field.key}`}>{field.title}</label><div className="original-value">{textTag(track.tags, field.key) || <span className="muted">Не указано</span>}</div><input id={`tag-${field.key}`} value={draft[field.key]} disabled={!writable || saving} onChange={event => { setDraft({ ...draft, [field.key]: event.target.value }); touch(); }} /></div>)}</div><div className="cover-editor"><div><h3>Обложка</h3><p className="muted small">{cover ? 'Новое изображение добавлено к черновику.' : activeProposal?.cover ? 'В предложении сохранена новая обложка. Ниже показана обложка текущего файла.' : track.has_art ? 'Изображение уже встроено в файл.' : 'В файле нет обложки.'} JPEG или PNG, до 10 МБ.</p></div><label className={`button secondary file-button ${!writable ? 'disabled' : ''}`}><ImagePlus size={18} />{track.has_art ? 'Заменить обложку' : 'Добавить обложку'}<input type="file" accept="image/jpeg,image/png" aria-label="Загрузить обложку" disabled={!writable} onChange={event => { void importCover(event.target.files?.[0]); event.target.value = ''; }} /></label></div><div className="notice info"><ShieldCheck size={19} /><span>Остальные теги и изображения сохраняются. Предложения внешних источников доступны выше. Таймкоды требуют проверки по аудио.</span></div></div>}
      <div className={`audio-player ${page === 'lyrics' ? '' : 'audio-compact'}`}><div className="audio-label"><AudioLines size={19} /><div><strong>Прослушать оригинальное аудио</strong><small>Прямое воспроизведение текущей версии файла</small></div><span className="mono">{formatTime(audioTime * 1000)}</span></div><audio ref={audioRef} controls preload="metadata" src={`/api/tracks/${encodeURIComponent(track.id)}/audio?v=${track.sha256}`} onTimeUpdate={event => setAudioTime(event.currentTarget.currentTime)} onLoadedMetadata={() => { setAudioSupported(true); setAudioError(''); }} onError={() => { setAudioSupported(false); setAudioError('Браузер не смог воспроизвести этот файл. Транскодирование не включено; разметка по позиции недоступна.'); }} />{audioError && <p className="small warning-text">{audioError}</p>}</div>
      {page === 'lyrics' && <LyricsEditor value={lrc} onChange={value => { setLrc(value); setLyricsTouched(true); touch(); }} disabled={!writable || saving} duration={track.duration} currentTime={audioTime} canStamp={audioSupported} onSeek={seconds => { if (audioRef.current) audioRef.current.currentTime = seconds; }} />}
      {hasUntimed && <div className="notice warning"><Clock3 size={19} /><span>Есть строки без таймкодов. Черновик можно сохранить, но записать синхронизированный текст в файл пока нельзя.</span></div>}{lyricsInvalid && <ErrorBox message={lyricsInvalid} />}
      <div className="editor-actions"><div className="action-hint"><ShieldCheck size={17} /><span>{changed ? 'Сначала сохраните предложение' : activeProposal ? 'Запись создаст резервную версию файла' : 'Файл остается без изменений'}</span></div><div className="button-row"><button className="button secondary" onClick={() => void save()} disabled={!writable || !changed || saving || busy}>{saving ? <Spinner label="Сохраняем" /> : <><Save size={18} />Сохранить предложение</>}</button><button className="button primary" onClick={() => void onJob('apply', { proposal_id: activeProposal?.id })} disabled={applyBlocked}><CheckCheck size={18} />Записать в файл</button></div></div></div>
    <section className="panel detail-tools"><h3>Файл и история</h3><dl className="file-facts"><div><dt>Путь</dt><dd className="break-word">{track.relative_path}</dd></div><div><dt>Ревизия</dt><dd className="mono break-word">{track.sha256}</dd></div><div><dt>Статус</dt><dd>{states[track.status] || track.status}</dd></div></dl><div className="button-row"><button className="button secondary" onClick={() => void onJob('audit')} disabled={busy || !summary?.capabilities.audit}><Activity size={17} />Проверить аудио</button><button className="button secondary" onClick={() => void onJob('publish')} disabled={busy || changed || !writable || !summary?.capabilities.publish}><FolderCheck size={17} />Опубликовать версию</button><button className="button subtle" onClick={() => { if (window.confirm('Восстановить предыдущую сохраненную версию этого файла? Текущий хеш будет проверен перед откатом.')) void onJob('rollback'); }} disabled={busy || changed || !writable || !track.history?.some(item => item.rollback_available && item.after_sha256 === track.sha256)}><Clock3 size={17} />Откатить запись</button></div><p className="muted small">Публикация копирует текущую версию в готовую коллекцию. Сохраненное предложение сначала нужно записать в файл.</p>{track.audit && <details><summary>Результат проверки аудио</summary><pre className="diagnostic">{JSON.stringify(track.audit, null, 2)}</pre></details>}{!!track.history?.length && <details><summary>История операций ({track.history.length})</summary><pre className="diagnostic">{JSON.stringify(track.history, null, 2)}</pre></details>}</section></>;
}

function LyricsEditor({ value, onChange, disabled, duration, currentTime, canStamp, onSeek }: { value: string; onChange: (value: string) => void; disabled: boolean; duration?: number; currentTime: number; canStamp: boolean; onSeek: (seconds: number) => void }) {
  const initial = useRef<{ lines: LyricLine[]; warnings: string[]; error: string } | null>(null);
  if (!initial.current) { try { initial.current = { ...parseLyrics(value), error: '' }; } catch (err) { initial.current = { lines: [], warnings: [], error: messageFor(err) }; } }
  const [lines, setLines] = useState<LyricLine[]>(initial.current.lines); const [warnings, setWarnings] = useState<string[]>(initial.current.warnings); const [error, setError] = useState(initial.current.error); const [raw, setRaw] = useState(value); const [showRaw, setShowRaw] = useState(!!initial.current.error); const [shift, setShift] = useState('0.5');
  const update = (next: LyricLine[]) => { setLines(next); const serialized = serializeLyrics(next); setRaw(serialized); onChange(serialized); setError(''); };
  function importText(text: string) { try { const parsed = parseLyrics(text); setWarnings(parsed.warnings); update(parsed.lines); setShowRaw(false); } catch (err) { setError(messageFor(err)); } }
  async function importFile(file?: File) { if (!file) return; if (file.size > 2 * 1024 * 1024) { setError('Файл текста больше 2 МБ.'); return; } try { importText(new TextDecoder('utf-8', { fatal: true }).decode(await file.arrayBuffer())); } catch { setError('Ожидается файл UTF-8. Пересохраните текст в UTF-8 и повторите импорт.'); } }
  function shiftLines(direction: number) { const seconds = Number(shift.replace(',', '.')); if (!Number.isFinite(seconds) || seconds < 0) { setError('Укажите положительный сдвиг в секундах.'); return; } const next = lines.map(line => ({ ...line, time: line.time === null ? null : Math.round(line.time + direction * seconds * 1000) })); const validation = validateLyrics(next, duration); if (validation) setError(validation); else update(next); }
  function move(index: number, delta: number) { const next = [...lines]; [next[index], next[index + delta]] = [next[index + delta], next[index]]; update(next); }
  const active = lines.reduce((result, line, index) => line.time !== null && line.time <= currentTime * 1000 ? index : result, -1);
  return <div className="lyrics-editor"><div className="section-intro"><div><h3>Синхронизированный текст</h3><p className="muted small">{lines.filter(line => line.time !== null).length} из {lines.length} строк с временем</p></div><div className="button-row"><label className={`button secondary file-button ${disabled ? 'disabled' : ''}`}><Upload size={17} />Импорт LRC<input type="file" accept=".lrc,.txt,text/plain" disabled={disabled} aria-label="Импортировать LRC или TXT" onChange={event => { void importFile(event.target.files?.[0]); event.target.value = ''; }} /></label><button className="button subtle" onClick={() => setShowRaw(!showRaw)}><BookOpen size={17} />{showRaw ? 'Строки' : 'Вставить текст'}</button></div></div>{error && <ErrorBox message={error} />}{warnings.map(warning => <p className="small warning-text" key={warning}>{warning}</p>)}{showRaw ? <div className="raw-editor"><label>Текст или LRC<textarea value={raw} disabled={disabled} onChange={event => { setRaw(event.target.value); onChange(event.target.value); }} placeholder="[00:12.500]Первая строка" rows={12} /></label><button className="button secondary" disabled={disabled} onClick={() => importText(raw)}>Применить к черновику</button><p className="muted small">При импорте положительный offset вычитается из времени строки. Например, 10.000 с с offset +500 станет 9.500 с.</p></div> : <><div className="lyrics-toolbar"><span className="muted small">Сдвинуть все таймкоды</span><div className="shift-controls"><button className="icon-button" disabled={disabled || !lines.length} onClick={() => shiftLines(-1)} title="Сдвинуть раньше" aria-label="Сдвинуть таймкоды раньше"><ArrowLeft size={17} /></button><input aria-label="Размер сдвига в секундах" inputMode="decimal" value={shift} onChange={event => setShift(event.target.value)} /><span>с</span><button className="icon-button" disabled={disabled || !lines.length} onClick={() => shiftLines(1)} title="Сдвинуть позже" aria-label="Сдвинуть таймкоды позже"><ArrowRight size={17} /></button></div></div><div className="lyric-lines">{lines.length === 0 ? <div className="empty compact"><ListMusic size={30} /><p>Добавьте текст или импортируйте LRC.<br />Строки без времени останутся черновиком.</p></div> : lines.map((line, index) => <div className={`lyric-line ${active === index ? 'current' : ''}`} key={line.id}><span className="line-index">{String(index + 1).padStart(2, '0')}</span><TimeInput time={line.time} disabled={disabled} index={index} onChange={time => update(lines.map((item, i) => i === index ? { ...item, time } : item))} onError={setError} /><button className="icon-button stamp-button" aria-label={`Отметить строку ${index + 1} текущим временем аудио`} title={canStamp ? 'Текущее время аудио' : 'Сначала загрузите аудио'} disabled={disabled || !canStamp} onClick={() => update(lines.map((item, i) => i === index ? { ...item, time: Math.round(currentTime * 1000) } : item))}><Clock3 size={16} /></button><input className="lyric-text" aria-label={`Текст строки ${index + 1}`} value={line.text} disabled={disabled} onChange={event => update(lines.map((item, i) => i === index ? { ...item, text: event.target.value } : item))} placeholder="Пустая строка" /><div className="line-actions"><button className="icon-button" aria-label={`Перейти к строке ${index + 1}`} disabled={!canStamp || line.time === null} onClick={() => onSeek((line.time || 0) / 1000)}><Music2 size={16} /></button><button className="icon-button" aria-label={`Переместить строку ${index + 1} вверх`} disabled={disabled || index === 0} onClick={() => move(index, -1)}><ArrowUp size={15} /></button><button className="icon-button" aria-label={`Переместить строку ${index + 1} вниз`} disabled={disabled || index === lines.length - 1} onClick={() => move(index, 1)}><ArrowDown size={15} /></button><button className="icon-button" aria-label={`Удалить строку ${index + 1}`} disabled={disabled} onClick={() => update(lines.filter((_, i) => i !== index))}><Trash2 size={15} /></button></div></div>)}</div><button className="button subtle" disabled={disabled} onClick={() => update([...lines, { id: crypto.randomUUID(), time: null, text: '' }])}><Plus size={17} />Добавить строку</button></>}<div className="quiet-note"><AudioLines size={17} />Таймкоды относятся к полному файлу. Задержка Bluetooth не добавляется к ним автоматически.</div></div>;
}
function TimeInput({ time, index, disabled, onChange, onError }: { time: number | null; index: number; disabled: boolean; onChange: (time: number | null) => void; onError: (message: string) => void }) { const [value, setValue] = useState(formatTime(time)); useEffect(() => setValue(formatTime(time)), [time]); return <input className="time-input mono" aria-label={`Время строки ${index + 1}`} placeholder="Без времени" value={value} disabled={disabled} onChange={event => setValue(event.target.value)} onBlur={() => { try { const next = parseTime(value); if (next !== time) onChange(next); } catch (err) { onError(messageFor(err)); setValue(formatTime(time)); } }} onKeyDown={event => { if (event.key === 'Enter') event.currentTarget.blur(); }} />; }

function JobsView({ jobs, refresh, onCancel }: { jobs: Job[]; refresh: () => Promise<void>; onCancel: (id: string) => Promise<void> }) { const [canceling, setCanceling] = useState(''); return <section className="panel jobs-panel"><div className="panel-heading"><div><h2>Очередь обработки</h2><span className="muted small">Обновляется автоматически каждые 4 секунды</span></div><button className="icon-button" aria-label="Обновить очередь" onClick={() => void refresh()}><RefreshCw size={18} /></button></div>{jobs.length === 0 ? <div className="empty"><div className="icon-surface"><Activity size={30} /></div><h3>Здесь пока тихо</h3><p>После сканирования или записи здесь появится задача<br />с этапами, результатом и возможными ошибками.</p></div> : <div className="jobs-list">{jobs.map(job => { const active = activeStates.includes(job.state); const percent = job.total > 0 ? Math.min(100, Math.round((job.completed + job.failed) / job.total * 100)) : 0; return <article className="job-card" key={job.id}><div className="job-top"><div className={`job-icon ${active ? 'is-active' : ''}`}>{active ? <LoaderCircle className={job.state === 'running' ? 'spin' : ''} size={22} /> : job.failed || job.state === 'failed' ? <CircleAlert size={22} /> : <CheckCheck size={22} />}</div><div className="job-title"><h3>{jobNames[job.kind] || job.kind}</h3><span className="muted small">{dateOf(job.created_at)}</span></div><Badge tone={job.failed || job.state === 'failed' ? 'warm' : active ? 'purple' : 'good'}>{job.cancel_requested && active ? 'Отмена запрошена' : states[job.state] || job.state}</Badge>{active && <button className="button subtle" disabled={job.cancel_requested || canceling === job.id} onClick={async () => { setCanceling(job.id); try { await onCancel(job.id); } finally { setCanceling(''); } }}>Отменить</button>}</div><div className="job-progress-label"><span>{states[job.stage] || job.stage || 'Подготовка'}</span><span>{job.total ? `${job.completed} завершено · ${job.failed} ошибок · всего ${job.total}` : 'Объем определяется'}</span></div><progress max={100} value={job.total ? percent : undefined} aria-label={`Прогресс ${jobNames[job.kind] || job.kind}`} />{job.error && <ErrorBox message={job.error} />}{job.cancel_requested && <p className="muted small">Уже выполненные изменения сохраняются. Текущая операция с файлом завершается безопасно.</p>}<JobResults job={job} /></article>; })}</div>}</section>; }

function SettingsView({ summary, theme, setTheme }: { summary: Summary | null; theme: string; setTheme: (value: string) => void }) { return <div className="settings-grid"><section className="panel settings-panel"><div className="section-icon"><Settings2 size={21} /></div><h2>Ваш экземпляр</h2><dl className="file-facts"><div><dt>Версия</dt><dd>{summary?.version || 'Нет данных'}</dd></div><div><dt>Доступ к файлам</dt><dd>{summary ? summary.read_only ? 'Только чтение' : 'Рабочая копия: запись разрешена' : 'Нет данных'}</dd></div><div><dt>Обработчик</dt><dd>{summary?.worker ? states[summary.worker.state] || summary.worker.state : 'Нет данных'}</dd></div><div><dt>Последний сигнал</dt><dd>{dateOf(summary?.worker.last_seen)}</dd></div>{summary?.roots?.work && <div><dt>Рабочая коллекция</dt><dd className="break-word">{summary.roots.work}</dd></div>}</dl><div className="settings-field"><label htmlFor="theme">Оформление</label><select id="theme" value={theme} onChange={event => setTheme(event.target.value)}><option value="system">Как в системе</option><option value="light">Светлое</option><option value="dark">Темное</option></select></div><p className="muted small">Пути, ресурсы обработчика и учетная запись владельца задаются в конфигурации Docker.</p></section><section className="panel settings-panel"><div className="section-icon purple"><WandSparkles size={21} /></div><h2>Возможности</h2><div className="capability-list">{[{ label: 'Каталог и проверка аудио', ready: summary?.capabilities.audit }, { label: 'Ручные предложения тегов и LRC', ready: summary?.capabilities.edit }, { label: 'Запись MP3 / FLAC / M4A / OGG / OPUS / WAV / AIFF', ready: summary?.capabilities.apply }, { label: 'Публикация готовой коллекции', ready: summary?.capabilities.publish }, { label: 'Поиск метаданных и текстов', ready: summary?.capabilities.metadata_search }, { label: 'Распознавание ShazamIO', ready: summary?.capabilities.recognition }, { label: 'ASR и выравнивание текста', ready: summary?.capabilities.asr }].map(item => <div key={item.label}><span>{item.label}</span><Badge tone={item.ready ? 'good' : ''}>{item.ready ? 'Доступно' : 'Недоступно'}</Badge></div>)}</div><p className="muted small">MusicBrainz, LRCLIB и Cover Art Archive подготавливают предложения. ShazamIO распознает локально подготовленные аудиоотпечатки без API-ключа, если отправка включена в конфигурации. Платные запросы отключены.</p></section><section className="panel settings-panel settings-wide"><div className="section-icon"><ShieldCheck size={21} /></div><h2>Три отдельных результата</h2><div className="safety-columns"><div><span className="step-number">01</span><h3>Рабочая копия</h3><p>Изменения записываются после сохранения предложения. Предыдущая версия нужна для отката.</p></div><div><span className="step-number">02</span><h3>Готовая коллекция</h3><p>Публикация создает отдельную копию принятой версии. Она еще не означает доставку на телефон.</p></div><div><span className="step-number">03</span><h3>Poweramp</h3><p>Проверьте теги, обложку, подсветку и перемотку офлайн. Проверка относится к конкретной версии файла.</p></div></div><div className="notice info"><CircleAlert size={19} /><span>Резервные версии на том же хранилище не заменяют независимый backup музыкальной коллекции.</span></div></section></div>; }

function JobResults({ job }: { job: Job }) {
  const [detail, setDetail] = useState<Job | null>(null); const [error, setError] = useState(''); const [loading, setLoading] = useState(false);
  async function load() { setLoading(true); setError(''); try { setDetail(await api<Job>('/jobs/' + encodeURIComponent(job.id))); } catch (err) { setError(messageFor(err)); } finally { setLoading(false); } }
  return <details onToggle={event => { if (event.currentTarget.open) void load(); }}><summary>Результаты по файлам</summary>{loading ? <Spinner /> : error ? <ErrorBox message={error} retry={() => void load()} /> : detail?.results?.length ? <><pre className="diagnostic">{JSON.stringify(detail.results, null, 2)}</pre><button className="button subtle" onClick={() => void load()}><RefreshCw size={15} />Обновить результаты</button></> : <p className="muted small">Результатов по отдельным файлам пока нет.</p>}</details>;
}
